import{_ as t}from"./chunks/theme-light.BboWfE89.js";import{_ as o,o as a,c as d,a3 as n}from"./chunks/framework.B3OtXxrP.js";const g=JSON.parse('{"title":"Writing in Blank","description":"","frontmatter":{},"headers":[],"relativePath":"guide/writing.md","filePath":"guide/writing.md"}'),r={name:"guide/writing.md"};function s(i,e,c,l,h,m){return a(),d("div",null,[...e[0]||(e[0]=[n('<h1 id="writing-in-blank" tabindex="-1">Writing in Blank <a class="header-anchor" href="#writing-in-blank" aria-label="Permalink to &quot;Writing in Blank&quot;">​</a></h1><p>Blank shows your text as it will look, not as markdown syntax. There are no toolbars: you format with <a href="./shortcuts">keyboard shortcuts</a> or by typing markdown, which Blank turns into formatting as you go.</p><img class="shot" src="'+t+'" alt="A document in Blank&#39;s light theme"><h2 id="format-as-you-type" tabindex="-1">Format as you type <a class="header-anchor" href="#format-as-you-type" aria-label="Permalink to &quot;Format as you type&quot;">​</a></h2><p>At the start of an empty line, type one of these to turn the line into a block:</p><table tabindex="0"><thead><tr><th>Type at the start of a line</th><th>Then</th><th>You get</th></tr></thead><tbody><tr><td><code>#</code> … <code>######</code></td><td>Space</td><td>Heading 1–6</td></tr><tr><td><code>-</code> <code>*</code> <code>+</code></td><td>Space</td><td>Bullet list</td></tr><tr><td><code>1.</code> (any number)</td><td>Space</td><td>Numbered list</td></tr><tr><td><code>&gt;</code></td><td>Space</td><td>Blockquote</td></tr><tr><td><code>---</code> <code>***</code> <code>___</code></td><td>Enter</td><td>Horizontal line</td></tr><tr><td><code>```</code> or <code>```lang</code></td><td>Enter</td><td>Code block</td></tr></tbody></table><p>Changed your mind? <code>Mod</code> <code>Z</code> right away gives you back the line as you typed it.</p><p>Inline markdown works too: <code>**bold**</code>, <code>*italic*</code>, <code>`code`</code>, <code>[title](url)</code> and plain URLs become formatting once you finish the word. See <a href="./autocorrect">Autocorrect</a> for everything Blank corrects.</p><h2 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to &quot;Images&quot;">​</a></h2><p>Type <code>![alt text](address)</code> and a space to add an image. The address can be:</p><ul><li>a file next to your document, like <code>![Chart](images/chart.png)</code>: keep the images in a folder beside the markdown file and they travel with it,</li><li>any file on your computer, like <code>![Logo](/home/me/logo.png)</code>,</li><li>a web address, like <code>![Map](https://example.com/map.png)</code>.</li></ul><p>Images next to your document appear as soon as the document has been saved, since Blank needs to know its folder. Until then Blank shows the alt text in their place. Large images shrink to the width of the page.</p><p>PDFs include every image at the size you see in Blank, including images from the web. If one can&#39;t be loaded, for example because you&#39;re offline, the PDF shows its alt text instead and Blank tells you which one.</p><h2 id="blank-remembers-your-document" tabindex="-1">Blank remembers your document <a class="header-anchor" href="#blank-remembers-your-document" aria-label="Permalink to &quot;Blank remembers your document&quot;">​</a></h2><p>Blank keeps what you write as you go, at least once a second and once more when you close the window, and restores it on the next start, together with the open file, the theme and the language. So you can close the window mid-thought without saving, and pick up right where you left off.</p><h2 id="save-open-and-export" tabindex="-1">Save, open and export <a class="header-anchor" href="#save-open-and-export" aria-label="Permalink to &quot;Save, open and export&quot;">​</a></h2><p>Documents are plain markdown files, so any other editor can open them.</p><table tabindex="0"><thead><tr><th>Command</th><th>Shortcut</th></tr></thead><tbody><tr><td>New file</td><td><code>Mod</code> <code>N</code></td></tr><tr><td>Open file</td><td><code>Mod</code> <code>O</code></td></tr><tr><td>Save</td><td><code>Mod</code> <code>S</code></td></tr><tr><td>Save as</td><td><code>Mod</code> <code>Shift</code> <code>S</code></td></tr><tr><td>Export as PDF</td><td><code>Mod</code> <code>Alt</code> <code>P</code></td></tr><tr><td>Export as Word</td><td><code>Mod</code> <code>Alt</code> <code>W</code></td></tr></tbody></table><p><code>Mod</code> is <code>Cmd</code> on macOS and <code>Ctrl</code> on Windows and Linux.</p><h3 id="open-word-documents" tabindex="-1">Open Word documents <a class="header-anchor" href="#open-word-documents" aria-label="Permalink to &quot;Open Word documents&quot;">​</a></h3><p><code>Mod</code> <code>O</code> also opens Word documents (.docx), and so does starting Blank with one, e.g. <code>blank report.docx</code>. Blank turns it into a new, untitled markdown document and never changes the Word file. Press <code>Mod</code> <code>S</code> to keep it: Blank suggests the same name with <code>.md</code>, next to the original. The top of the window shows <em>report.docx (imported)</em> until then.</p><p>Headings, bold and italic text, links, lists, quotes, code, line breaks and images come along. Images are stored inside the markdown file, so it stays a single file; large ones are scaled down to a size that still prints well. Word has more than markdown, so a few things change on the way, and Blank tells you when they do:</p><ul><li>tables become one line per row, with the cells separated by <code>|</code>,</li><li>footnotes move to the end of the document,</li><li>comments, headers and footers, underlining and colours are left out,</li><li>tracked changes count as accepted,</li><li>charts and drawings Blank can&#39;t show are replaced by their description,</li><li>numbered lists start at 1.</li></ul><p>Older formats (.doc, .odt, .rtf, .pages) can&#39;t be opened. Save them as .docx in their app first.</p><h3 id="word-documents-for-others" tabindex="-1">Word documents for others <a class="header-anchor" href="#word-documents-for-others" aria-label="Permalink to &quot;Word documents for others&quot;">​</a></h3><p>When someone needs your text in Word, press <code>Mod</code> <code>Alt</code> <code>W</code>. Blank writes a .docx that looks like its PDFs, with the same fonts and spacing, and that stays easy to edit: headings, quotes and code use real Word styles, so they show up in Word&#39;s style gallery, navigation pane and table of contents. Lists, links and images come along. Your markdown file stays as it is.</p><p>The document embeds Blank&#39;s font, IBM Plex Sans, so it looks the same in Word on computers without the font. LibreOffice and Google Docs ignore embedded fonts and use a similar one instead.</p><h2 id="the-status-bar" tabindex="-1">The status bar <a class="header-anchor" href="#the-status-bar" aria-label="Permalink to &quot;The status bar&quot;">​</a></h2><p>The top of the window shows the open file, <em>Untitled</em>, or the Word document an untitled document was imported from. The bottom shows the word and character count and the <a href="./autocorrect#language">autocorrect language</a>.</p>',29)])])}const f=o(r,[["render",s]]);export{g as __pageData,f as default};
